  "findings": [
    {"claim": "report", "severity": "should_fix", "finding": "The third next step reruns Brisk-S low with a retry on multi-hop and ambiguous-entity cases and says the result settles whether it 'holds every task and becomes the pick'. Two things that step does not settle also stand in the way. Its date-math pass rate is exactly on the 97% line, so on assumed counts it reads the wrong way half the time. And its overall p95 is 513 ms, so its slowest task is at least that slow and has not been read against 600 ms. Fix: add date-math cases to the rerun, and change the outcome to 'becomes the pick only if date math also holds and its per-task p95 stays under 600 ms'. Match the confidence clause's 'pending per-task latency' wording.", "continues": "new"}
  ],
  "resolved": ["f1.1", "f1.2", "f1.3", "f1.4", "f1.5"]
}
